class Solution {
    vector<int> original;
    mt19937 rng;
public:
    Solution(vector<int>& nums) : original(nums), rng(random_device{}()) {}

    vector<int> reset() { return original; }

    vector<int> shuffle() {
        vector<int> result = original;
        for (int i = (int)result.size() - 1; i > 0; --i) {
            uniform_int_distribution<int> distribution(0, i);
            swap(result[i], result[distribution(rng)]);
        }
        return result;
    }
};
